<?php
if(!defined('ABSPATH'))exit;
function dgs_public_url($mode=''){return $mode?add_query_arg('pre',$mode,dgs_page_url('admission')):dgs_page_url('admission');}
function dgs_public_form_start($type){return '<form class="dgp-form" method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('dgs_request_'.$type,'dgs_nonce',true,false).'<input type="hidden" name="action" value="dgs_submit_request"><input type="hidden" name="dgs_type" value="'.esc_attr($type).'"><div class="dg-honeypot" aria-hidden="true"><label>وب‌سایت<input name="website_url" tabindex="-1" autocomplete="off"></label></div>';}
function dgs_public_input($name,$label,$required=false,$attrs='',$type='text'){return '<label>'.esc_html($label).($required?' <b class="dgp-required">*</b>':'').'<input type="'.esc_attr($type).'" name="'.esc_attr($name).'" '.($required?'required':'').' '.$attrs.'></label>';}
function dgs_public_select($name,$label,$items,$required=true,$selected=''){return dgs_edu_select($name,$label.($required?' *':''),$items,$selected,$required);}
function dgs_public_consent(){return '<label class="dgp-consent"><input type="checkbox" name="consent" value="1" required>صحت اطلاعات را تأیید می‌کنم و با بررسی خصوصی اطلاعات توسط مسئولان مجاز مدرسه برای پیگیری درخواست موافقم.</label>';}
function dgs_public_success($type=''){if(dgs_att_get('dgs_sent')!=='1'||($type&&dgs_att_get('request_kind')!==$type))return '';return '<div class="dg-alert dg-success" role="status">درخواست شما ثبت شد. نتیجه بررسی و هماهنگی از طریق تماس مدرسه اطلاع داده می‌شود.</div>';}
function dgs_public_heading($title,$sub,$icon='requests'){return '<header class="dgp-heading"><h1>'.dgs_portal_icon($icon).esc_html($title).'</h1><p>'.esc_html($sub).'</p></header>';}
function dgs_public_art($type='school'){if($type==='contact')return '<svg aria-hidden="true" viewBox="0 0 240 160"><path d="M45 110V85a55 55 0 0 1 110 0v25M45 76H26v40h27V76zM155 76h20v40h-27V76zM151 117c0 22-23 22-36 22" fill="#ead8fa" stroke="#b98cdb" stroke-width="4"/><rect x="103" y="25" width="105" height="62" rx="14" fill="#f6eaff" stroke="#b98cdb" stroke-width="4"/><path d="M145 87l-14 18V87M123 44h63M123 59h44" fill="none" stroke="#b98cdb" stroke-width="4"/><rect x="96" y="132" width="26" height="12" rx="6" fill="#9d64c7"/></svg>';return '<svg aria-hidden="true" viewBox="0 0 280 165"><path d="M0 150h280" stroke="#c49ce1" stroke-width="3"/><path d="M64 70h152v80H64zM101 57h78v93h-78z" fill="#e0c8f4"/><path d="M49 69h64M168 69h61M85 56l55-30 56 30" fill="none" stroke="#ad7ad0" stroke-width="5"/><path d="M140 26V5l28 9-28 7" fill="#c18ae7" stroke="#ad7ad0" stroke-width="3"/><path d="M128 150v-33h24v33" fill="#fff5d3" stroke="#ad7ad0" stroke-width="3"/><g fill="#b583d8"><path d="M75 84h17v17H75zM75 111h17v17H75zM188 84h17v17h-17zM188 111h17v17h-17zM111 74h17v17h-17zM151 74h17v17h-17z"/></g><path d="M20 146v-25M247 146v-25" stroke="#a46cc7" stroke-width="4"/><ellipse cx="20" cy="110" rx="16" ry="27" fill="#c99be8"/><ellipse cx="247" cy="110" rx="16" ry="27" fill="#c99be8"/></svg>';}
function dgs_public_admission(){if(dgs_att_get('pre')==='school')return dgs_public_school();if(dgs_att_get('pre')==='class')return dgs_public_class(absint(dgs_att_get('academy_id')));return '<div class="dgp-page dgp-chooser">'.dgs_public_heading('پیش‌ثبت‌نام دانشگران','نوع پیش‌ثبت‌نام موردنظر خود را انتخاب کنید؛ ثبت درخواست اولیه به معنی پذیرش یا پرداخت نیست.','clipboard').'<div class="dgp-choice-grid"><a href="'.esc_url(dgs_public_url('school')).'">'.dgs_public_art().'<h2>پیش‌ثبت‌نام مدرسه</h2><p>پایه‌های دهم، یازدهم و دوازدهم</p><span class="dg-btn">تکمیل فرم مدرسه</span></a><a href="'.esc_url(dgs_public_url('class')).'">'.dgs_portal_icon('classes').'<h2>پیش‌ثبت‌نام کلاس تقویتی</h2><p>انتخاب کلاس و ثبت درخواست شرکت در آموزشگاه</p><span class="dg-btn">انتخاب کلاس تقویتی</span></a></div></div>';}
function dgs_public_school(){ $year=dgs_edu_current_year();$out='<div class="dgp-page dgp-school"><div class="dgp-hero">'.dgs_public_heading('پیش‌ثبت‌نام مدرسه دانشگران','فرم پیش‌ثبت‌نام پایه‌های دهم، یازدهم و دوازدهم؛ نتیجه پس از بررسی اطلاعات و مدارک از طریق تماس اطلاع داده می‌شود.','clipboard').'<div class="dgp-art">'.dgs_public_art().'</div></div>'.dgs_public_success('admission').'<div class="dgp-school-layout"><main>'.dgs_public_form_start('admission').'<nav class="dgp-steps"><a href="#dgp-student"><b>۱</b><strong>دانش‌آموز</strong><small>اطلاعات فردی و تحصیلی</small></a><a href="#dgp-parent"><b>۲</b><strong>اولیا</strong><small>اطلاعات تماس</small></a><a href="#dgp-documents"><b>۳</b><strong>مدارک</strong><small>بارگذاری و تأیید نهایی</small></a></nav><section class="dgp-card" id="dgp-student"><h2>'.dgs_portal_icon('users').' ۱. اطلاعات دانش‌آموز</h2><div class="dgp-grid three">'.dgs_public_input('first_name','نام',true,'maxlength="60" autocomplete="given-name"').dgs_public_input('last_name','نام خانوادگی',true,'maxlength="60" autocomplete="family-name"').dgs_public_input('student_national','کد ملی دانش‌آموز',true,'maxlength="10" minlength="10" inputmode="numeric" dir="ltr"').dgs_public_input('birth','تاریخ تولد',true,'placeholder="1388-02-24" maxlength="10" dir="ltr"').dgs_public_select('gender','جنسیت',array('male'=>'پسر','female'=>'دختر')).dgs_public_select('grade','پایه موردنظر',array(10=>'پایه دهم',11=>'پایه یازدهم',12=>'پایه دوازدهم')).'</div><div class="dgp-grid">'.dgs_public_select('field','رشته موردنظر',dgs_edu_fields()).'<label>سال تحصیلی<input value="'.esc_attr(dgs_fa_digits($year)).'" readonly><input type="hidden" name="request_year" value="'.esc_attr($year).'"></label></div></section><section class="dgp-card" id="dgp-parent"><h2>'.dgs_portal_icon('users').' ۲. اطلاعات اولیا <small>(تماس با مدرسه)</small></h2><div class="dgp-grid three">'.dgs_public_input('parent_name','نام و نام خانوادگی ولی',true,'maxlength="100"').dgs_public_select('relation','نسبت با دانش‌آموز',array('father'=>'پدر','mother'=>'مادر','guardian'=>'سرپرست قانونی','other'=>'سایر')).dgs_public_input('phone','شماره موبایل تماس اصلی',true,'maxlength="18" inputmode="tel" dir="ltr"').'</div><div class="dgp-grid">'.dgs_public_input('home_phone','شماره تماس ثابت (اختیاری)',false,'maxlength="11" inputmode="tel" dir="ltr"').dgs_public_input('prev_school','مدرسه فعلی (اختیاری)',false,'maxlength="100"').'</div></section><section class="dgp-card" id="dgp-documents"><h2>'.dgs_portal_icon('file').' ۳. بارگذاری مدارک</h2><p class="dgp-help">PDF، JPG یا PNG خوانا؛ حداکثر هر فایل ۵ مگابایت و محدود به سقف هاست.</p><div class="dgp-grid three">';foreach(array('birth_certificate'=>'تصویر شناسنامه (صفحه مشخصات)','national_card'=>'تصویر کارت ملی دانش‌آموز','report_card'=>'آخرین کارنامه تحصیلی') as $key=>$label)$out.='<label class="dgp-document">'.esc_html($label).' <b class="dgp-required">*</b><span class="dgp-drop">'.dgs_portal_icon('upload').'<strong>انتخاب فایل</strong><small>فایل را انتخاب یا اینجا رها کنید</small><input type="file" name="documents['.$key.']" accept=".pdf,.jpg,.jpeg,.png" required data-dgp-file></span><span class="dgp-file-name" aria-live="polite"></span></label>';$out.='</div></section>'.dgs_public_consent().'<details class="dgp-privacy"><summary>حریم خصوصی و نحوه بررسی درخواست</summary><p>اطلاعات و مدارک فقط برای بررسی پذیرش در اختیار مسئولان مجاز مدرسه قرار می‌گیرد. پیش‌ثبت‌نام، پذیرش قطعی یا ایجاد حساب دانش‌آموز نیست. برای هماهنگی با شماره تماس واردشده تماس گرفته می‌شود.</p></details><div class="dgp-submit"><button class="dg-btn">'.dgs_portal_icon('check').' ثبت درخواست پیش‌ثبت‌نام</button></div></form></main><aside class="dgp-card dgp-summary"><h2>'.dgs_portal_icon('clipboard').' خلاصه درخواست</h2><dl><div><dt>نوع درخواست</dt><dd>پیش‌ثبت‌نام مدرسه</dd></div><div><dt>پایه موردنظر</dt><dd data-dgp-grade>انتخاب نشده</dd></div><div><dt>سال تحصیلی</dt><dd>'.esc_html(dgs_fa_digits($year)).'</dd></div><div><dt>وضعیت</dt><dd><span class="dgp-pill">در حال تکمیل</span></dd></div></dl><h3>'.dgs_portal_icon('info').' نکات مهم</h3><ul><li>پذیرش نهایی پس از بررسی مدرسه انجام می‌شود.</li><li>اطلاعات باید با مدارک رسمی مطابقت داشته باشد.</li><li>مدارک واضح و خوانا بارگذاری شوند.</li><li>هیچ پرداختی در این مرحله انجام نمی‌شود.</li></ul><div class="dgp-summary-help"><h3>'.dgs_portal_icon('phone').' سؤالات و راهنمایی</h3><p>'.esc_html(dgs_setting('phone')?:'شماره دفتر مدرسه هنوز ثبت نشده است.').'</p></div><a href="'.esc_url(dgs_public_url()).'">بازگشت به انتخاب نوع پیش‌ثبت‌نام</a></aside></div></div>';return $out;}
function dgs_public_class($selected=0){$classes=get_posts(array('post_type'=>'dgs_class','post_status'=>'publish','numberposts'=>100,'orderby'=>'title','order'=>'ASC'));$options=array();foreach($classes as $c)$options[$c->ID]=$c->post_title;if(!$selected)$selected=(int)array_key_first($options);$class=isset($options[$selected])?get_post($selected):null;$out='<div class="dgp-page dgp-class">'.dgs_public_heading('پیش‌ثبت‌نام کلاس تقویتی','ثبت درخواست اولیه برای شرکت در کلاس‌های تقویتی و مرور دروس','timetable').dgs_public_success('class').'<aside class="dgp-notice">'.dgs_portal_icon('info').'<div><strong>این مرحله فقط ثبت درخواست پیش‌ثبت‌نام است.</strong><p>هیچ پرداختی انجام نمی‌شود؛ ثبت نهایی پس از بررسی ظرفیت و تأیید کادر آموزشگاه خواهد بود.</p></div></aside>';
 if(!$class)return $out.'<section class="dgp-card"><h2>کلاس‌های تقویتی</h2><p>'.($classes?'کلاس انتخاب‌شده در دسترس نیست.':'هنوز کلاس تقویتی منتشر نشده است.').'</p><a class="dg-btn" href="'.esc_url(dgs_page_url('academy')).'">مشاهده آموزشگاه</a></section></div>';
 $out.='<section class="dgp-card"><h2>'.dgs_portal_icon('classes').' کلاس انتخاب‌شده</h2><div class="dgp-selected-class"><h3>'.dgs_portal_icon('education').esc_html($class->post_title).'</h3><div class="dgp-class-facts">';foreach(array('_dgs_teacher_name'=>array('users','مدرس'),'_dgs_schedule'=>array('timetable','برنامه برگزاری'),'_dgs_start_date'=>array('timetable','تاریخ شروع'),'_dgs_capacity'=>array('users','ظرفیت اعلام‌شده')) as $key=>$v){$value=$key==='_dgs_teacher_name'&&function_exists('dgs_catalog_teacher_name')?dgs_catalog_teacher_name($selected):get_post_meta($selected,$key,true);$out.='<div>'.dgs_portal_icon($v[0]).'<b>'.esc_html($v[1]).'</b><span>'.esc_html($value!==''?$value:'توسط آموزشگاه اعلام می‌شود').'</span></div>';}$out.='</div></div></section><section class="dgp-card"><h2>'.dgs_portal_icon('edit').' فرم پیش‌ثبت‌نام</h2><p>اطلاعات زیر را به‌دقت تکمیل کنید.</p>'.dgs_public_form_start('class').'<div class="dgp-grid">'.dgs_public_input('name','نام و نام خانوادگی دانش‌آموز',true,'maxlength="100"').dgs_public_select('grade','پایه تحصیلی',array(10=>'پایه دهم',11=>'پایه یازدهم',12=>'پایه دوازدهم')).dgs_public_select('field','رشته تحصیلی',dgs_edu_fields()).dgs_public_input('phone','شماره تماس والدین',true,'maxlength="18" inputmode="tel" dir="ltr"').'</div>'.dgs_public_select('class_id','کلاس انتخاب‌شده',$options,true,$selected).'<label>توضیحات (اختیاری)<textarea name="message" rows="3" maxlength="2000" placeholder="نکات یا درخواست‌های خود را بنویسید…"></textarea></label>'.dgs_public_consent().'<div class="dgp-submit"><button class="dg-btn">'.dgs_portal_icon('send').' ثبت درخواست پیش‌ثبت‌نام</button></div></form></section><section class="dgp-next"><h2>'.dgs_portal_icon('clipboard').' مراحل پس از ثبت درخواست</h2><div class="dgp-grid three"><p><b>۱. ثبت درخواست</b><br>تکمیل و ارسال فرم</p><p><b>۲. بررسی آموزشگاه</b><br>بررسی ظرفیت و شرایط کلاس</p><p><b>۳. اعلام نتیجه</b><br>هماهنگی از طریق تماس مدرسه</p></div></section><a href="'.esc_url(dgs_public_url()).'">بازگشت به انتخاب نوع پیش‌ثبت‌نام</a></div>';return $out;}
function dgs_public_contact_form(){return dgs_public_form_start('contact').'<div class="dgp-grid">'.dgs_public_input('name','نام و نام خانوادگی',true,'maxlength="100"').dgs_public_input('phone','شماره تماس',true,'maxlength="18" inputmode="tel" dir="ltr"').'</div>'.dgs_public_select('contact_subject','موضوع پیام',dgs_public_topics()).'<label>متن پیام <b class="dgp-required">*</b><textarea name="message" maxlength="2000" rows="4" required placeholder="متن پیام خود را بنویسید…"></textarea></label>'.dgs_public_consent().'<button class="dg-btn">'.dgs_portal_icon('send').' ارسال پیام</button></form>';}
function dgs_public_topics(){return array('information'=>'دریافت اطلاعات مدرسه','admission'=>'پیش‌ثبت‌نام مدرسه','class'=>'کلاس تقویتی','suggestion'=>'پیشنهاد و انتقاد','other'=>'سایر موارد');}
function dgs_public_counsel_form(){return dgs_public_form_start('counseling').'<div class="dgp-grid">'.dgs_public_input('name','نام و نام خانوادگی دانش‌آموز',true,'maxlength="100"').dgs_public_input('phone','شماره موبایل والدین',true,'maxlength="18" inputmode="tel" dir="ltr"').'</div>'.dgs_public_select('grade','پایه تحصیلی موردنظر',array(10=>'پایه دهم',11=>'پایه یازدهم',12=>'پایه دوازدهم')).dgs_public_input('counsel_topic','موضوع درخواست مشاوره',true,'maxlength="200" placeholder="مثلاً انتخاب رشته یا برنامه‌ریزی تحصیلی"').'<label>زمان‌های پیشنهادی حضور <b class="dgp-required">*</b><textarea name="preferred_times" rows="3" maxlength="1000" required placeholder="چند بازه روز و ساعت مناسب را بنویسید…"></textarea></label>'.dgs_public_consent().'<div class="dgp-submit"><button class="dg-btn">'.dgs_portal_icon('attendance').' ثبت درخواست</button></div></form>';}
function dgs_public_contact(){ $phone=dgs_setting('phone');$address=dgs_setting('address');$map=dgs_setting('map_url');if(!$map&&$address)$map='https://www.google.com/maps/search/?api=1&query='.rawurlencode($address);$out='<div class="dgp-page dgp-contact"><div class="dgp-hero">'.dgs_public_heading('ارتباط و درخواست مشاوره','برای دریافت اطلاعات بیشتر، طرح پرسش یا درخواست مشاوره تحصیلی حضوری و تلفنی از راه‌های زیر با مدرسه در ارتباط باشید.','phone').'<div class="dgp-art">'.dgs_public_art('contact').'</div></div>'.dgs_public_success().'<div class="dgp-contact-facts"><section class="dgp-card"><h2>'.dgs_portal_icon('phone').' تلفن دفتر مدرسه</h2><strong dir="ltr">'.esc_html($phone?:'هنوز ثبت نشده است').'</strong></section><section class="dgp-card"><h2>'.dgs_portal_icon('pin').' نشانی مدرسه</h2><p>'.esc_html($address?:'نشانی مدرسه هنوز ثبت نشده است.').'</p>'.($map?'<a href="'.esc_url($map).'" target="_blank" rel="noopener noreferrer">مشاهده روی نقشه</a>':'').'</section><section class="dgp-card"><h2>'.dgs_portal_icon('clock').' ساعات کاری مدرسه</h2><p>'.esc_html(dgs_setting('office_hours')?:'ساعات کاری هنوز ثبت نشده است.').'</p></section></div><div class="dgp-grid dgp-contact-body"><section class="dgp-card"><h2>'.dgs_portal_icon('mail').' ارسال پیام به مدرسه</h2><p class="dgp-help">سؤال، پیشنهاد یا درخواست خود را بنویسید تا مسئول مدرسه پیگیری کند.</p>'.dgs_public_contact_form().'</section><section class="dgp-card"><h2>'.dgs_portal_icon('pin').' موقعیت مدرسه روی نقشه</h2><div class="dgp-map-illustration" aria-label="نمایش شماتیک نقشه؛ برای موقعیت دقیق لینک نقشه را باز کنید"><svg aria-hidden="true" viewBox="0 0 400 320"><rect width="400" height="320" fill="#e9e5e9"/><path d="M0 35h400M0 125h400M0 230h400M55 0v320M170 0v320M300 0v320" stroke="#fff" stroke-width="13"/><path d="M0 300L350 0" stroke="#fff" stroke-width="16"/><path d="M65 45h90v65H65zM311 135h80v80h-80zM185 241h100v65H185z" fill="#d5e9cf"/><path d="M230 141c0 32-30 55-30 55s-30-23-30-55a30 30 0 0 1 60 0" fill="#7b28a2"/><circle cx="200" cy="141" r="11" fill="#fff"/></svg></div><p class="dgp-help">نمایش شماتیک است؛ موقعیت دقیق از لینک نقشه مدرسه باز می‌شود.</p>'.($map?'<a class="dg-btn dg-btn-outline" href="'.esc_url($map).'" target="_blank" rel="noopener noreferrer">مشاهده نقشه بزرگ‌تر</a>':'<p class="dgp-help">نشانی یا لینک نقشه را در تنظیمات مدرسه وارد کنید.</p>').'</section></div><section class="dgp-counsel-banner"><div><h2>'.dgs_portal_icon('users').' مشاوره تحصیلی</h2><p>برای انتخاب رشته، برنامه‌ریزی تحصیلی یا ادامه مسیر آموزشی درخواست مشاوره ثبت کنید. زمان دقیق پس از بررسی با شما هماهنگ می‌شود.</p><button class="dg-btn" type="button" data-dgp-dialog="dgp-counsel-dialog">'.dgs_portal_icon('timetable').' درخواست مشاوره حضوری</button></div><div class="dgp-art">'.dgs_public_art().'</div></section><dialog class="dgp-dialog" id="dgp-counsel-dialog"><button class="dgp-close" type="button" data-dgp-close aria-label="بستن">×</button><div class="dgp-dialog-icon">'.dgs_portal_icon('timetable').'</div><h2>درخواست مشاوره حضوری</h2><p>برای هماهنگی با مشاوران مدرسه فرم زیر را تکمیل کنید. زمان جلسه پس از تماس مدرسه مشخص می‌شود.</p>'.dgs_public_counsel_form().'</dialog></div>';return $out;}
function dgs_public_request_view($type,$class=0){if($type==='admission')return dgs_public_school();if($type==='class')return dgs_public_class($class);if($type==='contact')return dgs_public_contact_form();if($type==='counseling')return dgs_public_counsel_form();return '';}
function dgs_public_validate_fields($input,$type){foreach($input as $v)if(!is_scalar($v))return dgs_edu_error('field','اطلاعات فرم معتبر نیست.');$out=array('request_year'=>dgs_edu_current_year());if($type==='admission'){$fields=array('first_name','last_name','student_national','birth','gender','parent_name','relation','request_year','field');foreach($fields as $key)if(trim((string)($input[$key]??''))==='')return dgs_edu_error('required','اطلاعات دانش‌آموز و ولی را کامل کنید.');$out['first_name']=sanitize_text_field($input['first_name']);$out['last_name']=sanitize_text_field($input['last_name']);if(dgs_edu_length($out['first_name'])>60||dgs_edu_length($out['last_name'])>60)return dgs_edu_error('name','نام و نام خانوادگی بیش از حد طولانی است.');$out['name']=$out['first_name'].' '.$out['last_name'];$out['student_national']=dgs_edu_digits($input['student_national']);$out['birth']=str_replace('/','-',dgs_edu_digits($input['birth']));$out['gender']=$input['gender'];$out['relation']=$input['relation'];if(!dgs_edu_national_id($out['student_national'])||!dgs_record_birth($out['birth'])||dgs_rq_date($out['birth'])>dgs_att_today()||!in_array($out['gender'],array('male','female'),true)||!in_array($out['relation'],array('father','mother','guardian','other'),true)||dgs_edu_year($input['request_year'])!==dgs_edu_current_year())return dgs_edu_error('identity','کد ملی، تاریخ تولد، جنسیت، نسبت یا سال تحصیلی معتبر نیست.');$out['home_phone']=dgs_edu_digits((string)($input['home_phone']??''));if($out['home_phone']!==''&&!preg_match('/^0[0-9]{10}$/D',$out['home_phone']))return dgs_edu_error('phone','تلفن ثابت ۱۱ رقمی باشد.');}
 if($type==='admission'||$type==='class')if(!isset(dgs_edu_fields()[$input['field']??'']))return dgs_edu_error('field','رشته تحصیلی را انتخاب کنید.');if($type==='class'){$c=absint($input['class_id']??0);$g=get_post_meta($c,'_dgs_grade',true);if(in_array((string)$g,array('10','11','12'),true)&&(string)($input['grade']??'')!==(string)$g)return dgs_edu_error('grade','پایه انتخابی با کلاس مطابقت ندارد.');}
 if($type==='contact'){$topic=(string)($input['contact_subject']??'');if(!isset(dgs_public_topics()[$topic])||trim((string)($input['message']??''))==='')return dgs_edu_error('message','موضوع و متن پیام را وارد کنید.');$out['contact_subject']=$topic;$out['message']='موضوع: '.dgs_public_topics()[$topic]."\n".sanitize_textarea_field($input['message']);}
 if($type==='counseling'){$topic=sanitize_text_field((string)($input['counsel_topic']??''));$times=sanitize_textarea_field((string)($input['preferred_times']??''));if(!$topic||!$times||dgs_edu_length($topic)>200||dgs_edu_length($times)>1000)return dgs_edu_error('counsel','موضوع مشاوره و زمان‌های پیشنهادی را کامل کنید.');$out['counsel_topic']=$topic;$out['preferred_times']=$times;$out['message']='موضوع: '.$topic."\nزمان‌های پیشنهادی: ".$times;}return $out;}
function dgs_public_check_documents($raw){if(!is_array($raw)||!is_array($raw['error']??null))return dgs_edu_error('documents','سه مدرک خواسته‌شده را بارگذاری کنید.');foreach(array('birth_certificate','national_card','report_card') as $key)if(($raw['error'][$key]??-1)!==UPLOAD_ERR_OK||!is_scalar($raw['size'][$key]??null)||$raw['size'][$key]<1||$raw['size'][$key]>5*1024*1024)return dgs_edu_error('documents','شناسنامه، کارت ملی و کارنامه لازم‌اند؛ هر فایل حداکثر ۵ مگابایت باشد.');if(count($raw['error'])!==3)return dgs_edu_error('documents','فقط سه مدرک مشخص‌شده را بارگذاری کنید.');return true;}
function dgs_public_request_return($type,$class=0){if($type==='admission')return dgs_public_url('school');if($type==='class')return add_query_arg('academy_id',$class,dgs_public_url('class'));return dgs_page_url('contact');}
function dgs_public_page_active(){$p=get_option('dgs_pages',array());return (!empty($p['admission'])&&is_page((int)$p['admission']))||(!empty($p['contact'])&&is_page((int)$p['contact']))||is_singular('dgs_class');}
add_action('init',function(){add_shortcode('daneshgaran_admission','dgs_public_admission');add_shortcode('daneshgaran_contact','dgs_public_contact');},20);
add_filter('body_class',function($classes){if(dgs_public_page_active())$classes[]='dgp-public-page';return $classes;});
add_action('wp_enqueue_scripts',function(){if(!dgs_public_page_active())return;wp_register_style('dgs-public-requests',false,array(),DGS_VERSION);wp_enqueue_style('dgs-public-requests');wp_add_inline_style('dgs-public-requests',file_get_contents(DGS_PATH.'assets/public-requests.css'));wp_register_script('dgs-public-requests',false,array(),DGS_VERSION,true);wp_enqueue_script('dgs-public-requests');wp_add_inline_script('dgs-public-requests',file_get_contents(DGS_PATH.'assets/public-requests.js'));});
add_action('wp_footer',function(){if(get_template()!=='daneshgaran'||dgs_is_role_portal())return;echo '<template id="dgp-nav-icons"><span data-url="'.esc_attr(dgs_page_url('admission')).'">'.dgs_portal_icon('clipboard').'</span><span data-url="'.esc_attr(dgs_page_url('contact')).'">'.dgs_portal_icon('phone').'</span></template>';},10);
add_action('wp_footer',function(){if(dgs_public_page_active()&&!is_user_logged_in())echo '<template id="dgp-guest"><span class="dgp-guest-avatar">'.dgs_portal_icon('users').'</span><span class="dgp-guest-label"><strong>مهمان</strong><small>کاربر عمومی</small></span></template>';},10);
